UPDATE acc_transaction
   SET kind = #{kind}, tx_date = #{txDate}, client_name = #{clientName, jdbcType=VARCHAR}, subject_id = #{subjectId, jdbcType=BIGINT},
       amount = #{amount}, method = #{method}, bank_account_id = #{bankAccountId, jdbcType=BIGINT}, card_id = #{cardId, jdbcType=BIGINT},
       note = #{note, jdbcType=VARCHAR}
 WHERE id = #{id}
